{
  "case_id": "xsu_sg_003_severity_assessment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret fremhæver 'arbejdsevne ved siden af studiet' og 'nærmest ikke i stand til at arbejde' som det afgørende, og det er ikke i kilderne (SU-loven § 7, stk. 3 siger 'meget betydelige begrænsninger i evnen til at påtage sig erhvervsarbejde'). Det hævder også, at Uddannelses- og Forskningsstyrelsen og ikke Udbetaling Danmark vurderer sagen, hvilket strider mod bekendtgørelsen § 36 og vejledningen (Udbetaling Danmark). Rubrikkens centrale momenter udelades: restsymptomer/bivirkninger, rimelig medvirken til behandling og sygdomsvarighed, gentagelser og tilbagefaldsrisiko."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Fire kritiske elementer kræves. Individuel samlet vurdering og dokumentation er delvist med. Begrænsninger i daglig funktion er delvist dækket. Behandlingens effekt nævnes kun overfladisk, uden restsymptomer/bivirkninger og rimelig medvirken. Sygdommens varighed, gentagne perioder og tilbagefaldsrisiko mangler næsten helt (kun 'langvarige' og 'varierer')."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret forsøger at besvare, hvad der vægtes ved vurderingen af sværhedsgraden, og giver en liste over momenter. Det afviger delvist ved at sige, at Udbetaling Danmark ikke er den vurderende myndighed, men besvarer stadig spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde (ingen lov, bekendtgørelse eller vejledning)."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer uunderstøttet indhold. Det hævder, at Uddannelses- og Forskningsstyrelsen er den vurderende myndighed i stedet for Udbetaling Danmark. Det fremhæver 'nærmest ikke i stand til at arbejde' og 'almindeligt lønnet arbejde ved siden af uddannelsen' som tærskel/test. Det siger også, at 'svært ved selve studiet' ikke er nok, og at vurderingen 'især' handler om arbejdsevnen. Intet af dette findes i de udleverede kilder."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Den krævede kvalifikation er, at momenterne er eksempler i en konkret helhedsvurdering. Svaret nævner 'typisk' og 'samlet vurdering', så delvist bevaret. Men det gør arbejdsevnen til det dominerende kriterium og udelader de centrale momentgrupper. Kravet om 'varig' er med, men 'meget betydelige begrænsninger' er omformuleret."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: diagnosen alene er ikke nok, vægten ligger på funktionsbegrænsninger og arbejdsevne, og konklusionen følger af det."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "'Normalt' om Uddannelses- og Forskningsstyrelsen gengiver ikke kilderne, som entydigt peger på Udbetaling Danmark. 'Nærmest ikke i stand til at arbejde' skærper kildens 'meget betydelige begrænsninger'. 'Især' om arbejdsevnen gør ét moment dominerende."
    }
  },
  "xhaile_coverage": {
    "A14": {
      "label": "partial",
      "reason": "Svaret nævner lægelig dokumentation, som bør beskrive tilstanden og dens praktiske følger, og en samlet vurdering. Det dækker ikke velbeskrevet/lægefagligt dokumenteret som krav, og det udelader flere momenter fra kilden: restsymptomer/bivirkninger, rimelig medvirken, sygdomsvarighed, gentagelser og tilbagefald."
    }
  },
  "overall_notes": "Svaret er læseligt og peger delvist på de rette momenter: funktionsbegrænsninger, behandling og dokumentation. Men det angiver ingen kilder, flytter myndighedsansvaret til en anden styrelse, indfører en uunderstøttet tærskel om at være 'nærmest ikke i stand til at arbejde' og udelader flere centrale momenter fra vejledningen."
}

